class JusPrinAccountNoteTestCase(TestCase):
    """The JusPrin login and signup pages say an Obico account works there only
    when it does: JusPrin branding over Obico's accounts, not JusPrin's own host."""

    def setUp(self):
        base, _ = Syndicate.objects.get_or_create(id=1, defaults={'name': 'base'})
        jusprin, _ = Syndicate.objects.get_or_create(id=2, defaults={'name': 'jusprin'})
        base.sites.add(Site.objects.get_or_create(domain='testserver', defaults={'name': 'testserver'})[0])
        jusprin.sites.add(Site.objects.create(domain='jusprin.testserver', name='JusPrin'))

    def notes(self, **headers):
        login = self.client.get('/accounts/login/', **headers).content.decode()
        signup = self.client.get('/accounts/signup/', **headers).content.decode()
        return ('use the same account' in login, 'do NOT sign up again' in signup)

    def test_jusprin_branding_on_obicos_host(self):
        self.assertEqual(self.notes(HTTP_USER_AGENT='JusPrin/1.9'), (True, True))

    def test_jusprins_own_host(self):
        self.assertEqual(self.notes(HTTP_HOST='jusprin.testserver'), (False, False))
EOF
